import { useState } from "react";
import NoteContext from "./noteContext";

const NoteState = (props) => {
  const host = "http://localhost:5000";
  const notesInitial = []

  const [notes, setNotes] = useState(notesInitial);

  //Add a note
  const getNotes = async() => {
    //api call here
    const response = await fetch(`${host}/api/notes/fetchallnotes`, {
      method: "GET",
      headers: {
        "Content-Type": "application/json",
        "auth-token":
          "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
      }
    });
    const json = await response.json()
    console.log(json)
    setNotes(json)
  }

  //Add a note
  const addNote = async(title, description, tag) => {
    //api call here
    const response = await fetch(`${host}/api/notes/addnote`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "auth-token":
          "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
      },
      body: JSON.stringify({title, description, tag}),
    });
    console.log("Adding a new note");
    const note = {
      _id: "6889f129a8c326ed6d615c17",
      user: "6889b74785f048911598b2c3",
      title: title,
      description: description,
      tag: tag,
      date: "2025-07-30T10:17:13.493Z",
      __v: 0,
    };
    setNotes(notes.concat(note));
  };

  //Delete a Note
  const deleteNote = async(id) => {
    const response = await fetch(`${host}/api/notes/deletenote/${id}`, {
      method: "DELETE",
      headers: {
        "Content-Type": "application/json",
        "auth-token":
          "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
      }
    });
    const json = await response.json();
    console.log(json)
    console.log("Deleting the note with id" + id);
    const newNotes = notes.filter((note) => {
      return note._id !== id;
    });
    setNotes(newNotes);
  };

  //Update a note
  const editNote = async (id, title, description, tag) => {
    //api call here
    const response = await fetch(`${host}/api/notes/editNote/${id}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "auth-token":
          "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJ1c2VyIjp7ImlkIjoiNjg4OWI3NDc4NWYwNDg5MTE1OThiMmMzIn0sImlhdCI6MTc1Mzg1NTgxNX0.3pbNVVp_Nr23TLEgc85qMHni-7_y2-P5T3tNQE6Qc8I",
      },
      body: JSON.stringify({title, description, tag}),
    });
    const json = await response.json();
    console.log(json);

    //logic to edit in client

    for (let index = 0; index < notes.length; index++) {
      const element = notes[index];
      if (element._id === id) {
        element.title = title;
        element.description = description;
        element.tag = tag;
      }
    }
  };

  return (
    <NoteContext.Provider value={{ notes, addNote, deleteNote, editNote, getNotes }}>
      {props.children}
    </NoteContext.Provider>
  );
};

export default NoteState;
